SELECT SUM(regular_hours * hourly_usd) AS regular_payroll_cost
FROM dataset
WHERE department = 'Engineering';

SELECT SUM(list_price * available_units) AS estimated_retail_value
FROM dataset
WHERE is_active = 'Yes';

SELECT 
  COUNT(CASE WHEN payment_state = 'Paid' THEN 1 END) * 100.0 / COUNT(*) AS percentage_paid
FROM dataset;

SELECT 
  (COUNT(CASE WHEN escalated = 'Yes' THEN 1 END) * 100.0 / COUNT(*)) AS percentage_escalated
FROM dataset;

SELECT 
  ROUND(100.0 * SUM(CASE WHEN was_refunded = 'Yes' THEN 1 ELSE 0 END) / COUNT(*), 2) AS refund_percentage
FROM dataset;

SELECT 
  (COUNT(CASE WHEN was_absent = 'Yes' THEN 1 END) * 100.0 / COUNT(*)) AS absence_percentage
FROM dataset;

SELECT 
  ROUND(
    100.0 * COUNT(CASE WHEN available_units < reorder_threshold THEN 1 END) / COUNT(*), 
    2
  ) AS percentage_below_reorder
FROM dataset;

SELECT SUM(net_sales) AS online_revenue_from_coastal
FROM dataset
WHERE sales_channel = 'Online' AND territory = 'Coastal';
